import mongoose from"mongoose";const productSchema=new mongoose.Schema({name:{type:String,required:!0},description:{type:String,required:!0},description2:{type:String,required:!1},price:{type:Number,required:!0},image:{type:Array,required:!0},category:{type:String,required:!0},slug:{type:String,required:!0},categorySlug:{type:String,required:!0},subcategorySlug:{type:String,required:!1},subCategory:{type:String,required:!1},subCategory2:{type:String,required:!1},subCategorySlug2:{type:String,required:!1},bestSeller:{type:Boolean},destacado:{type:Boolean,required:!1},quantity:{type:Number,required:!0,default:1},metaDescription:{type:String,required:!1},metaTitle:{type:String,required:!1},date:{type:Number,required:!0},variants:[{size:{type:String,required:!0},color:{type:String,required:!0},stock:{type:Number,required:!0}}],anos:{type:String,required:!1},textPersonal:{type:String,required:!1}}),productModel=mongoose.models.product||mongoose.model("product",productSchema);export default productModel;